      "answer": 1,
      "answerLabel": "B",
      "context": "54 TIM LINTON -PROOFREADING & EDITING SERVICE Posted: June 9 I am working as a freelance publishing agent, proofreader and editor. My specialties are educational books and scientific papers. I have experience as a proofreader and editor at major publishing houses, including Camellia Books and Longbottom Education. I have a degree in education from Gunstone University of Science and a postgraduate degree in literature from Halliwell University in Nova Scotia. My previous work includes Camellia Books'Basic Physics for High School Students, for which the publisher received an award, and Longbottom Education's Environmental Issues. Please feel free to contact either of those publishers for a reference. I offer an excell ent service at competitive rates. Interested writers may contact me directly at tlinton@gfpars. com. To: Tim Linton <tlinton@gfpars. com> From: Lauren Chang <lchang@camelliabooks. com> Date: June 16 Subject: Long time no see! Dear Tim, I received a call from May Merriweather, who wanted to check your credentials after viewing your online posting. She informed me that you were now freelancing. Obviously, I highly recommended you as a proofreader for the textbook she is working on. Everyone at Camellia Books has fond memories of you, and we were very sorry when you made the move back to Seattle, although I am sure you are enjoying being closer to your family. Since you resigned, we have started using freelance editors more often, and we would like to have you on our list of potential collaborators. I would appreciate it if you could get back to me and let me know whether or not it is OK to contact you with work in the future. Sincerely, Lauren Chang Chief Editor -Camellia Books",
