      "context": "56 COfflPAII AIR □□□ BAGGAGE TAG Baggage ID: GHS812893 NOTICE: If your baggage is lost, you will receive a maximum daily allowance of $50 per item until it is found, or until a total payout of $1,750 per item is reached. If you experience any difficulties during your tr ip with Compass Air, please contact the support service using the Web site at www. compassair. com. Flight #: CP734 Departing from: SEATTLE/ US Landing in: VIENNA/ AT To: Wendy Lee <wlee@lionway. com> From: Toby Smith <tsmith@compassair. com> Date: September 3 Subject: Your baggage Dear Ms. Lee, I am happy to inform you that we have found your luggage (Baggage ID: GHS8 I 2893). It seems that the ground staff in Glen Ridge mislabeled it, and it was sent to Australia rather than your destination, Austria. We have calculated that you will have been without your luggage for a total of20 days and have made a payment of$2,000 to your bank account in accordance with the notice on your baggage tag, and the confirmation e-mail you received immediately after booking your ticket. Please let me know where you would like to have your bags sent. However, you should keep in mind that we are limited to destinations that Compass Air flies to. Sincerely, Toby Smith Customer Service Representative— Compass Air To: Toby Smith <tsmith@compassair. com> From: Wendy Lee <wlee@lionway. com> Date: September 3 Subject: RE: Your baggage Dear Mr. Smith, Thank you for your e-mail regarding my lost baggage. It has been two weeks since I came to Austria, and I had given up hope of getting my belongings back. I will be in Linz, Austria for a few more months and have already replaced most of the things that were lost. If I pay for shipping, would you have my luggage delivered from Seattle Airport to my hometown of Aberdeen? I am sure you still have my address details in your system. Regards, Wendy Lee",
