      "answer": 1,
      "answerLabel": "B",
      "context": "92 McQueen Bros Best in the Tri-State Area! Testimonials The Workshop Past Projects McQueen Bros has been in the classic and vintage car restoration business for more than 40 years. We have a highly trained team of mechanics and upholsterers who can return virtually any vehicle to its former glory, no matter how neglected it has become. Last year we were recognized with a trophy from the Connecticut Better Business Bureau for our lasting success and our high customer satisfaction rating. This achievement can be attributed to our incredibly high standards and excellent staff training. Our professional restorers understand the need for authenticity and affordability and strive to achieve a perfect balance of both. We can pick up vehicles anywhere in the tri-state area and as far afield as Rhode Is land although additional fees may apply depending on distance. We are especially well known for our thoroughness when it comes to refinishing interiors. We source original fabrics and cushioning from trusted suppliers to ensure your treasured vehicle really does look like new. To encourage the restoration of particularly old vehicles, we offer reduced rates on labor for pre-antique cars. Such cars are defined in the industry as being over 50 years old. We are happy to help by carrying out an entire project or a specific job so give us a call at 555 2933 to arrange a free price estimate",
