      "context": "94 Goodness Gracious Foods, Inc. Service Agreement This service agreement outlines the services provided by Goodness Gracious Foods, lnc., to the consumer (\"you\"). It is important that you read and understand these terms and conditions completely before signing at the bottom. If you would like any of the items below explained in more detail, please call one of our customer service representatives. 1. Services: You have chosen the \"B\" package, the contents of which are explained in detail in the Goodness Gracious Foods brochure. — [ I]—. A container will be delivered to your door weekly. 2. Changes to and Termination of the Agreement: Depending on the ability of wholesalers to provide us with fresh food items, Goodness Gracious Foods may be forced to alter some of the package contents. You will be notified at least 14 days in advance and be given the option to terminate the contract if the change is unsatisfactory. [2]—. 3. Customer Obligations: You will be charged $30 a week for the \"B\" package. In the interest of product quality, a short survey is included once a month. Customers are expected to fill out the survey in return for a $2 discount on their monthly bill. — [3]—. 4. Renewal: After 12 months of signing this document, the contract will expire. You will be given the option to renew the contract without having to pay any joining fees. — [4]—. Additionally, you will be eli gible for the introductory specials Goodness Gracious Foods is offering at the time. By signing this document, I acknowledge that I have read and fully understood the conditions explained above. Signed: Date:",
