      "answer": 3,
      "answerLabel": "D",
      "context": "E-Mail Message To: I Jack Pollard <jpollard@redcliffcc. org> From: I Pearl Ito <pito@redcliffcc. org> Subject: I Congestion problem Date: I Febmary 19 Dear Mr. Pollard, I an1 writing with regard to the proposal you raised at the meeting of council members this morning. You suggested adding lanes to Willian1 Street in order to ease traffic congestion in the suburbs of Franklin and Goldberg. It is extremely important that we do something to solve the congestion problem as soon as possible. However, I believe that your plan to widen the road will only act as a very temporary fix. I would like to make an alternative suggestion. Rather than making it easier for people to drive, I think we should encourage them to use public transportation more. The council provides an excell ent train and bus network, which is largely underused. Rather than widening roads, I believe we should provide more free parking at stations and bus terminals around town. This would cost less than widening Willi Street and has the added benefits of generating revenue through ticket sales and improving the convenience for commuters. I am eager to hear your though Sincerely, Pearl Ito",
