      "context": "E-Mail Message To: Skai Kahuna <skahuna@hansonconventioncenter. com> From: Glen Winston <gwinston@gemanagement. com> Date: December 19 Subject: Convention rooms Dear Ms. Kahuna: I must congratulate you and your staff on the excell ent work you did hosting the Eighth Annual Farming Machinery Exposition. The event was a great success and the other organizers and I feel that it was largely because your staff were so attentive. Nevertheless, I would like to draw your attention to a number of issues. These need to be addressed before I would be willing to reserve your venue for the same event next year, which is scheduled for November 12. Many participants near the back of the room complained that they could not hear the presenters or see the screen easily. I think the speaker system needs to be upgraded, and I suggest either replacing the screen with a larger one or adding a second screen. According to the survey we conducted after the event, the seat cushioning has worn out on some of the chairs. I would also like to meet with you at some tin1e to discuss pricing options as we are on a tighter budget next year. Sincerely, Glen Winston GE Management I• = 11111 t! l - To: Glen Winston <gwinston@gernanagernent. com> From: Skai Kahuna <skahuna@hansonconventioncenter. com> Date: December 20 Subject: RE: Convention rooms Dear Mr. Winston: Thank you for your kind words. I an1 sorry to hear of the problems you encountered and I will ensure that we do our best to rectify them. Just this week, we replaced our projector, which enabled us to double the size of the screen. I'm sure you will find our new equipment more than adequate. Another guest had informed us of the speaker problem and I happyto infonn you that it has already been deaIt with. With regard to the issue brought up in the surveys, I will have my staff take care of that imn1ediately. I hope we will hear from you regarding the event in November. Skai Kahuna Manager -Hanson Convention Center.. 142 Hanson Convention Center Schedule Week 50 Date Event Location Sunday, December 12 Holloway Publishing Book Launch Main Hall Monday、December13 Ninth Annual Farming Machinery Exposition Main Hall Tuesday, December 14 Reed Aeronautical Symposium Room B Wednesday, December 15 No Events Thursday, December 16 Stedman Construction Display Main Hall Friday, December 17 No Events",
