      "context": "144 Synopsis The Secret Garden from Cauliflower Books is the fictional story of Ronald Peterson, a man who receives an anonymous letter in the mail. Inside, there is a map that shows the location of a hidden door in his own house. An attached note promises that it leads to a secret garden at the end of a tunnel. What follows is an exciting story of adventure and intrigue as Ronald solves puzzles and overcomes obstacles as the tunnel is far bigger and more complicated than it first seems. This is Gregory Hill's second book and it shows how he has grown as a writer. While he has remained in the fantasy genre, this is a much longer book written for a much more mature audience. It is the source material for an upcoming film of the same name by Fermont Pictures. 1111111 To: Miles Thompson <mthompson@bookswithmiles. com> From: Jill Houseman <houseman@cauliflowerbooks. com> Subject: Book review Date: February 28 Dear Mr. Thompson, My name is Jill Houseman and I have recently been hired in the Cauliflower Books'publicity division. A colleague of mine informed me that you reviewed The Secret Garden. I would like to ask you to review another of our soon-to-be-released books. It is call ed The Sugar Battle, and we have hopes that it will be a bestseller. I sent you a copy yesterday so it should arrive by March 4 at the latest. We will both be at Brigadoon Books on the release date of The Secret Garden to celebrate its launch. Could you pass me the review then? This will allow us to discuss it face to face. By the way, I have noticed that you have only one genre checked on your reviewer profile and that has not changed since you first registered. Nevertheless, Cauliflower Books publishes a broad range of novels including romance, adventure, and drama. If you would ever like to receive a wider variety of genres, please let us know. Sincerely, Jil l Houseman Publicity Divis ion, Cauliflower Books NEW IN FICTION Released on March 15. Fifty thousand copies already sold! \"A heartwarming story about an unlikely adventurer.\" Carry Strong, Literarypros. com \"I hope the movie lives up to the expectations of this book's many fans.\" Silvia Van Jansen, Story Field Magazine \"As soon as I finished reading it, I bought five more copies to give to friends.\" Miles Thompson, Books with Miles \"Gregory Hill's new book is a wonderfully original tale for people of all ages.\" Ken Morris、TheBradfield Post",
